"""Generates the unrolled V2-family kernels (bench/proto/commit_accumulate_*.wgsl).

    uv run python bench/proto/gen_variants.py

Each variant: workgroup = (chunk of CHUNK positions, group of COLS columns, block); A2[q] staged in
workgroup memory as 32-bit limbs; every thread owns CPT coefficients (i, i + 512/CPT, ...) x COLS
columns, accumulated as 16-bit digits in 8 u32 (2 vec4) per (column, coefficient).
"""
from pathlib import Path

HERE = Path(__file__).resolve().parent

HEAD = """// {title}
// Generated by gen_variants.py — edit the generator, not this file.
// dispatch: (num_chunks, colcap/{cols}, blocks). Partials per chunk; reduce.wgsl sums chunks and canonicalizes.
override CHUNK: u32 = 128u;
const COLS: u32 = {cols}u;
const CPT: u32 = {cpt}u;                 // coefficients per thread
const WG: u32 = 512u / CPT;
@group(0) @binding(0) var<uniform> P: Params;
@group(0) @binding(1) var<storage, read> A2: array<vec4<u32>>;
@group(0) @binding(2) var<storage, read> HOT: array<u32>;   // code bytes, row stride = colcap bytes
@group(0) @binding(3) var<storage, read_write> PART: array<vec4<u32>>;
var<workgroup> S: array<vec4<u32>, 1024>;

@compute @workgroup_size(WG)
fn main(@builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>) {{
  let i = lid.x;
  let chunk = wid.x;
  let g = wid.y;
  let b = wid.z;
{acc_decl}
  let q0 = chunk * CHUNK;
  let row_u32 = P.colcap / 4u;
  for (var qq = 0u; qq < CHUNK; qq++) {{
    let q = q0 + qq;
    workgroupBarrier();
    for (var k = i; k < 1024u; k += WG) {{
      S[k] = A2[q * 1024u + k];
    }}
    workgroupBarrier();
    let row0 = (b * P.positions + q) * 32u;
    for (var r = 0u; r < 32u; r++) {{
      let hbase = (row0 + r) * row_u32 + g * (COLS / 4u);
{words}
      let sbase = i - r * 16u;
{cols_code}
    }}
  }}
  let cbase = g * COLS;
{store}
}}
"""


def build(name, title, cols, cpt):
    step = 512 // cpt
    acc = []
    for c in range(cols):
        for t in range(cpt):
            acc.append(f"  var lo{c}_{t} = vec4<u32>(0u);\n  var hi{c}_{t} = vec4<u32>(0u);")
    words = "\n".join(f"      let w{k} = HOT[hbase + {k}u];" for k in range(cols // 4))
    cols_code = []
    for c in range(cols):
        body = ["          let j0 = (sbase - code) & 1023u;"]
        for t in range(cpt):
            j = "j0" if t == 0 else f"((j0 + {t * step}u) & 1023u)"
            body.append(f"          {{ let x = S[{j}]; lo{c}_{t} += x & vec4<u32>(0xFFFFu); hi{c}_{t} += x >> vec4<u32>(16u); }}")
        body = "\n".join(body)
        cols_code.append(f"""      {{
        let code = (w{c // 4} >> {(c % 4) * 8}u) & 0xFFu;
        if (code < 16u) {{
{body}
        }}
      }}""")
    store = []
    for c in range(cols):
        for t in range(cpt):
            store.append(f"  {{ let o = ((chunk * P.colcap + cbase + {c}u) * P.blocks + b) * 512u + i + {t * step}u; "
                         f"PART[o * 2u] = lo{c}_{t}; PART[o * 2u + 1u] = hi{c}_{t}; }}")
    src = HEAD.format(title=title, cols=cols, cpt=cpt, acc_decl="\n".join(acc), words=words,
                      cols_code="\n".join(cols_code), store="\n".join(store))
    (HERE / f"{name}.wgsl").write_text(src)


build("commit_accumulate_v2b", "V2b: 8 columns x 1 coefficient per thread (512 threads), 64 accumulator words.", 8, 1)
build("commit_accumulate_v3", "V3: 4 columns x 1 coefficient per thread (512 threads), 32 accumulator words.", 4, 1)
build("commit_accumulate_v4", "V4: 8 columns x 2 coefficients per thread (256 threads), 128 accumulator words.", 8, 2)
build("commit_accumulate_v5", "V5: 4 columns x 2 coefficients per thread (256 threads), 64 accumulator words.", 4, 2)
